Here is the commit message:
dm mpath: Add missing dm_put_device when failing to get scsi
 dh name

When commit fd81bc5cca8f ("scsi: device_handler: Return error pointer in
scsi_dh_attached_handler_name()") added code to fail parsing the path if
scsi_dh_attached_handler_name() failed with -ENOMEM, it didn't clean up
the reference to the path device that had just been taken. Fix this, and
steamline the error paths of parse_path() a little.

Fixes: fd81bc5cca8f ("scsi: device_handler: Return error pointer in scsi_dh_attached_handler_name()")
Cc: stable@vger.kernel.org
Signed-off-by: Benjamin Marzinski <bmarzins@redhat.com>
Signed-off-by: Mikulas Patocka <mpatocka@redhat.com>

Here is the root cause:
In the `parse_path()` function in `drivers/md/dm-mpath.c`, after taking a reference to the path device using `dm_get_device()`, the code calls `scsi_dh_attached_handler_name()`. If that function fails (e.g., returns `-ENOMEM`), the original error handling jumped directly to the `bad` label without calling `dm_put_device()` to release the device reference, causing a resource leak. The patch adds a new `bad_put_device` label that first calls `dm_put_device()` before falling through to `bad`, ensuring proper cleanup.

Here is the patch:

 static struct pgpath *parse_path(struct dm_arg_set *as, struct path_selector *ps,
 				 struct dm_target *ti)
 {
 	int r;
 	struct pgpath *p;
 	struct multipath *m = ti->private;
 	struct request_queue *q;
 	const char *attached_handler_name = NULL;

 	/* we need at least a path arg */
 	if (as->argc < 1) {
 		ti->error = "no device given";
 		return ERR_PTR(-EINVAL);
 	}

 	p = alloc_pgpath();
 	if (!p)
 		return ERR_PTR(-ENOMEM);

 	r = dm_get_device(ti, dm_shift_arg(as), dm_table_get_mode(ti->table),
 			  &p->path.dev);
 	if (r) {
 		ti->error = "error getting device";
 		goto bad;
 	}

 	q = bdev_get_queue(p->path.dev->bdev);
 	attached_handler_name = scsi_dh_attached_handler_name(q, GFP_KERNEL);
 	if (IS_ERR(attached_handler_name)) {
 		if (PTR_ERR(attached_handler_name) == -ENODEV) {
 			if (m->hw_handler_name) {
 				DMERR("hardware handlers are only allowed for SCSI devices");
 				kfree(m->hw_handler_name);
 				m->hw_handler_name = NULL;
 			}
 			attached_handler_name = NULL;
 		} else {
 			r = PTR_ERR(attached_handler_name);
-			goto bad;
+			ti->error = "error allocating handler name";
+			goto bad_put_device;
 		}
 	}
 	if (attached_handler_name || m->hw_handler_name) {
 		INIT_DELAYED_WORK(&p->activate_path, activate_path_work);
 		r = setup_scsi_dh(p->path.dev->bdev, m, &attached_handler_name, &ti->error);
 		kfree(attached_handler_name);
-		if (r) {
-			dm_put_device(ti, p->path.dev);
-			goto bad;
-		}
+		if (r)
+			goto bad_put_device;
 	}

 	r = ps->type->add_path(ps, &p->path, as->argc, as->argv, &ti->error);
-	if (r) {
-		dm_put_device(ti, p->path.dev);
-		goto bad;
-	}
+	if (r)
+		goto bad_put_device;

 	return p;
- bad:
+
+bad_put_device:
+	dm_put_device(ti, p->path.dev);
+bad:
 	free_pgpath(p);
 	return ERR_PTR(r);
 }



